stopifnot(file.exists(out('01_partitions/COMPLETE')));md<-qread(out('00_audit/cell_metadata.qs'));sizes<-fread(out('01_partitions/all_cluster_sizes.tsv'));N<-nrow(md);allmet<-list();allprof<-list();baselines<-list()
metric<-function(sel,hi){tp<-sum(sel&hi);nc<-sum(sel);nh<-sum(hi);data.table(n_full=length(hi),n_cluster=nc,n_high=nh,TP=tp,FP=nc-tp,FN=nh-tp,TN=length(hi)-nc-nh+tp,precision=if(nc)tp/nc else NA_real_,recall=if(nh)tp/nh else NA_real_,F1=if(nc+nh)2*tp/(nc+nh)else NA_real_,enrichment=if(nc&nh)(tp/nc)/(nh/length(hi))else NA_real_)}
for(b in c('C8','C12','C16'))for(h in c('NMF','UCell')){sel<-if(b=='C8')md$r04==b else md$r06==b;d<-metric(sel,md[[paste0(h,'_high')]]);d[,`:=`(baseline=b,high=h)];baselines[[length(baselines)+1L]]<-d};base<-rbindlist(baselines);wt(base,'02_coverage/old_baselines.tsv')
for(p in unique(sizes$partition)){lab<-qread(out(paste0('01_partitions/',p,'.qs')));stopifnot(identical(lab$cell_id,md$cell_id));sz<-sizes[partition==p]
 for(h in c('NMF','UCell')){d<-data.table(cluster=lab$cluster,hi=md[[paste0(h,'_high')]])[,.(TP=sum(hi)),by=cluster];d<-merge(d,sz,by='cluster');d[,`:=`(n_full=N,n_cluster=n_cells,n_high=sum(md[[paste0(h,'_high')]]),high=h)];d[,`:=`(FP=n_cluster-TP,FN=n_high-TP,TN=n_full-n_cluster-n_high+TP,precision=TP/n_cluster,recall=TP/n_high,F1=2*TP/(n_cluster+n_high),enrichment=(TP/n_cluster)/(n_high/n_full))];stopifnot(sum(d$TP)==unique(d$n_high),sum(d$n_cluster)==N);d[,minPR:=pmin(precision,recall)];d[,pareto_within_partition:=vapply(seq_len(.N),function(i)!any(precision>=precision[i]&recall>=recall[i]&(precision>precision[i]|recall>recall[i])),logical(1))];allmet[[length(allmet)+1L]]<-d}
 d<-copy(md);d[,cluster:=lab$cluster];pr<-d[,.(usage_mean=mean(usage10),usage_median=median(usage10),usage_q25=quantile(usage10,.25),usage_q75=quantile(usage10,.75),usage_q95=quantile(usage10,.95),usage_zero=mean(usage10==0),ucell_mean=mean(ucell10),ucell_median=median(ucell10),ucell_q25=quantile(ucell10,.25),ucell_q75=quantile(ucell10,.75),ucell_q95=quantile(ucell10,.95),ucell_zero=mean(ucell10==0)),by=cluster];pr[,partition:=p];allprof[[p]]<-pr
}
met<-rbindlist(allmet);met[,pareto_global:=vapply(seq_len(.N),function(i)!any(precision>=precision[i]&recall>=recall[i]&(precision>precision[i]|recall>recall[i])),logical(1)),by=high];wt(met,'02_coverage/all_clusters_two_high.tsv');wt(rbindlist(allprof),'02_coverage/all_cluster_MP10_distributions.tsv');wt(met[pareto_global|pareto_within_partition],'02_coverage/PR_Pareto_fronts.tsv')
setorderv(met,c('partition','high','F1','minPR','precision','cluster_numeric'),c(1,1,-1,-1,-1,1));win<-met[,.SD[1],by=.(partition,high)];can<-win[,.(won_for=paste(sort(high),collapse=';')),by=.(partition,result_id,cluster,cluster_numeric,representation,resolution,n_cells,member_hash)];setorder(can,representation,resolution,cluster_numeric);can[,candidate_id:=sprintf('K%02d',.I)]
wide<-dcast(met,result_id~high,value.var=c('precision','recall','F1','enrichment','TP'));can<-merge(can,wide,by='result_id',sort=FALSE);setorder(can,candidate_id)
for(h in c('NMF','UCell')){b<-base[baseline=='C8'&high==h];P<-can[[paste0('precision_',h)]];R<-can[[paste0('recall_',h)]];F<-can[[paste0('F1_',h)]];can[,(paste0('vs_C8_',h)):=ifelse(P>=b$precision & R>=b$recall & (P>b$precision|R>b$recall),'P_R_both_improve_or_one_equal',ifelse(F>b$F1,'F1_improves_P_or_R_declines','not_improved'))]}
# Overall recommendations fixed from coverage only, before DEG.
wglob<-copy(met);setorderv(wglob,c('high','F1','minPR','precision','cluster_numeric','representation','resolution'),c(1,-1,-1,-1,1,1,1));best<-wglob[,.SD[1],by=high];wt(best,'03_candidates/global_F1_winners_preDE.tsv');can[,recommended:=result_id%in%best$result_id]
contrasts<-list();locals<-list()
for(rep in reps){g<-qread(graphpath(rep));for(p in unique(can[representation==rep,partition])){lab<-qread(out(paste0('01_partitions/',p,'.qs')));cls<-sizes[partition==p][order(cluster_numeric),cluster];fac<-match(lab$cluster,cls);ind<-sparseMatrix(i=seq_len(N),j=fac,x=1,dims=c(N,length(cls)));conn<-as.matrix(crossprod(ind,g%*%ind));ns<-as.numeric(table(factor(lab$cluster,levels=cls)));avg<-conn/outer(ns,ns);diag(avg)<-NA
 for(k in which(can$partition==p)){c<-can[k];ci<-match(c$cluster,cls);vals<-avg[ci,];local<-if(all(is.na(vals)))NA_character_ else cls[which.max(replace(vals,is.na(vals),-Inf))];outside<-met[partition==p & cluster!=c$cluster];carrier<-sapply(c('NMF','UCell'),function(h){z<-outside[high==h][order(-TP,cluster_numeric)];if(nrow(z))z$cluster[1]else NA_character_});primary<-if(grepl('NMF',c$won_for))'NMF'else'UCell';extra<-unname(carrier[primary]);if(!is.na(extra)&&identical(extra,local))extra<-NA_character_
 can[k,`:=`(local_cluster=local,NMF_outside_carrier=unname(carrier['NMF']),UCell_outside_carrier=unname(carrier['UCell']),extra_cluster=extra)];locals[[length(locals)+1L]]<-data.table(candidate_id=c$candidate_id,partition=p,cluster=cls,mean_SNN=vals)
 controls<-data.table(control_type=c('rest','local',if(!is.na(extra))'carrier'),control_cluster=c('rest',local,if(!is.na(extra))extra));for(j in 1:nrow(controls)){ct<-controls[j];left<-md$cell_id[lab$cluster==c$cluster];right<-if(is.na(ct$control_cluster))character() else if(ct$control_cluster=='rest')md$cell_id[lab$cluster!=c$cluster]else md$cell_id[lab$cluster==ct$control_cluster];hash<-digest(list(left=sort(left),right=sort(right),model=config$DE),algo='sha256');contrasts[[length(contrasts)+1L]]<-data.table(comparison_id=paste(c$candidate_id,ct$control_type,sep='_'),candidate_id=c$candidate_id,partition=p,representation=rep,resolution=c$resolution,cluster=c$cluster,control_type=ct$control_type,control_cluster=ct$control_cluster,n_left=length(left),n_right=length(right),left_hash=memberhash(left),right_hash=memberhash(right),model_key=hash)}}};rm(g);gc()}
wt(can,'03_candidates/candidates_preDE.tsv');wt(rbindlist(contrasts),'03_candidates/comparisons_preDE.tsv');wt(rbindlist(locals),'03_candidates/local_SNN_strengths.tsv');saveq(can,'03_candidates/candidates.qs')
