 for(field in c('sample','dataset','source'))for(h in c('NMF','UCell')){d<-data.table(level=as.character(md[[field]]),sel=sel,hi=md[[paste0(h,'_high')]])[,.(n_pool=.N,n_candidate=sum(sel),n_high=sum(hi),TP=sum(sel&hi)),by=level];d[,`:=`(precision=ifelse(n_candidate>0,TP/n_candidate,NA_real_),recall=ifelse(n_high>0,TP/n_high,NA_real_),candidate_fraction=n_candidate/n_pool,contribution=n_candidate/sum(sel),candidate_id=c$candidate_id,field=field,high=h)];cov[[length(cov)+1L]]<-d}
 qcs[[i]]<-md[sel,.(n_cells=.N,nCount_mean=mean(nCount_counts),nCount_median=as.numeric(median(nCount_counts)),nFeature_mean=mean(nFeature_counts),nFeature_median=as.numeric(median(nFeature_counts)),percent_mt_mean=mean(percent.mt,na.rm=TRUE),percent_mt_N=sum(is.finite(percent.mt))),by=.(sample,dataset,source)][,candidate_id:=c$candidate_id]
 mppr[[i]]<-data.table(candidate_id=c$candidate_id,MP=mp,raw_mean=colMeans(M[md$cell_id[sel],,drop=FALSE]))
};cov<-rbindlist(cov);wt(cov,'02_coverage/candidate_source_coverage.tsv');wt(rbindlist(qcs),'03_candidates/candidate_sample_QC.tsv');wt(rbindlist(mppr),'03_candidates/candidate_14MP_profiles.tsv');wt(cov[field=='sample',.(n_samples=.N,n_P_valid=sum(is.finite(precision)),n_P_NA=sum(is.na(precision)),n_R_valid=sum(is.finite(recall)),n_R_NA=sum(is.na(recall)),n_high_zero_recall=sum(n_high>0&TP==0),P_sample_equal=mean(precision,na.rm=TRUE),R_sample_equal=mean(recall,na.rm=TRUE),P_median=median(precision,na.rm=TRUE),R_median=median(recall,na.rm=TRUE)),by=.(candidate_id,high)],'02_coverage/sample_equal_summary.tsv')
# q80/q95 ONLY for coverage-selected overall winners.
