# Flow tables for every cluster and actual candidate membership overlap.
flows<-list();jacs<-list();baseline_track<-list()
for(rep in reps)for(i in 1:(length(resolutions)-1)){p<-pid(rep,resolutions[i]);q<-pid(rep,resolutions[i+1]);a<-qread(out(paste0('01_partitions/',p,'.qs')));b<-qread(out(paste0('01_partitions/',q,'.qs')));d<-as.data.table(table(from=a$cluster,to=b$cluster))[N>0];d[,`:=`(partition_from=p,partition_to=q)];d[,fraction_from:=N/sum(N),by=from];d[,fraction_to:=N/sum(N),by=to];flows[[length(flows)+1L]]<-d}
for(i in 1:nrow(can)){a<-can[i];la<-qread(out(paste0('01_partitions/',a$partition,'.qs')))$cluster==a$cluster;for(baseid in c('C8','C12','C16')){lb<-if(baseid=='C8')md$r04==baseid else md$r06==baseid;it<-sum(la&lb);baseline_track[[length(baseline_track)+1L]]<-data.table(candidate_id=a$candidate_id,baseline=baseid,intersection=it,Jaccard=it/sum(la|lb),fraction_of_baseline=it/sum(lb),fraction_of_candidate=it/sum(la))};if(i<nrow(can))for(j in (i+1):nrow(can)){b<-can[j];cross<-a$representation!=b$representation;adj<-!cross & abs(match(a$resolution,resolutions)-match(b$resolution,resolutions))==1;if(!cross & !adj)next;lb<-qread(out(paste0('01_partitions/',b$partition,'.qs')))$cluster==b$cluster;it<-sum(la&lb);jacs[[length(jacs)+1L]]<-data.table(candidate_A=a$candidate_id,candidate_B=b$candidate_id,type=if(cross)'RAW_Z'else'adjacent_resolution',intersection=it,Jaccard=it/sum(la|lb),fraction_A=it/sum(la),fraction_B=it/sum(lb))}}
